function validate([rating]) {
  if (!Array.isArray(rating) || rating.length < 3 || rating.length > 1000) return 'rating needs 3 to 1000 values.';
  if (rating.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each rating is a whole number from 1 to 100000.';
  if (new Set(rating).size !== rating.length) return 'All ratings must be different.';
  return null;
}

