function numTeams(rating) {
  const n = rating.length;
  let teams = 0;

  // Enumerate the middle soldier of every team.
  for (let j = 1; j < n - 1; j++) {
    let leftLess = 0;
    let leftMore = 0;
    for (let i = 0; i < j; i++) {
      if (rating[i] < rating[j]) {
        leftLess++;
      } else {
        leftMore++;
      }
    }
    let rightLess = 0;
    let rightMore = 0;
    for (let k = j + 1; k < n; k++) {
      if (rating[k] < rating[j]) {
        rightLess++;
      } else {
        rightMore++;
      }
    }
    // Rising teams go small-left, big-right; falling teams the other way round.
    teams += leftLess * rightMore + leftMore * rightLess;
  }
  return teams;
}

