function numTeams(rating) {
  let count = 0;
  for (let i = 0; i < rating.length; i++)
    for (let j = i + 1; j < rating.length; j++)
      for (let k = j + 1; k < rating.length; k++) {
        const a = rating[i], b = rating[j], c = rating[k];
        if ((a < b && b < c) || (a > b && b > c)) count++;
      }
  return count;
}

