function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 900 + pick(101) : 3 + pick(8);
  const top = size === 'large' || rand() < 0.5 ? 100000 : 2 * n;
  const seen = new Set();
  while (seen.size < n) seen.add(1 + pick(top));
  const rating = [...seen];
  const shape = pick(5);
  if (shape === 0) rating.sort((a, b) => a - b);
  else if (shape === 1) rating.sort((a, b) => b - a);
  else if (shape === 2) {
    // Mostly sorted: a few random swaps in an ascending row.
    rating.sort((a, b) => a - b);
    for (let s = 0; s < Math.max(1, n >> 3); s++) {
      const x = pick(n), y = pick(n);
      [rating[x], rating[y]] = [rating[y], rating[x]];
    }
  }
  return [rating];
}
